13	// foldPathCase lowercases: Windows paths compare case-insensitively, and the
14	// markers below are already lowercase.
15	func foldPathCase(p string) string { return strings.ToLower(p) }
16	
17	// Windows install.ps1 one-liners, in the README's shapes. Printed, never
18	// auto-run. windowsInstallCmd is the bare stable form; arguments go through
19	// windowsInstallWithArgs, the iex "& {...}" form that can bind them.
20	const (
21		windowsInstallURL      = "https://entire.io/install.ps1"
22		windowsInstallCmd      = "irm " + windowsInstallURL + " | iex"
23		windowsInstallWithArgs = `iex "& {$(irm ` + windowsInstallURL + `)} %s"`
24	)
