26	// scoopConfigPath is Scoop's config.json, which records relocated install roots.
27	func scoopConfigPath() string {
28		if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
29			return filepath.Join(xdg, "scoop", "config.json")
30		}
31		profile := os.Getenv("USERPROFILE")
32		if profile == "" {
33			return ""
34		}
35		return filepath.Join(profile, ".config", "scoop", "config.json")
36	}
37	
38	type scoopConfigFile struct {
39		RootPath   string `json:"root_path"`
40		GlobalPath string `json:"global_path"`
41	}
42	
43	func readScoopConfig() scoopConfigFile {
44		path := scoopConfigPath()
45		if path == "" {
46			return scoopConfigFile{}
47		}
48		data, err := os.ReadFile(path) //nolint:gosec // fixed per-user config location, not user input
49		if err != nil {
50			return scoopConfigFile{}
51		}
52		var cfg scoopConfigFile
53		if err := json.Unmarshal(data, &cfg); err != nil {
54			return scoopConfigFile{}
55		}
56		return cfg
57	}
58	
59	func scoopRoots() []string {
60		cfg := readScoopConfig()
61		var roots []string
62		for _, r := range []string{os.Getenv("SCOOP"), os.Getenv("SCOOP_GLOBAL"), cfg.RootPath, cfg.GlobalPath} {
63			if r != "" {
64				roots = append(roots, filepath.Join(r, "apps"))
65			}
66		}
67		return roots
68	}
69	
70	// scoopAppsMarker is the default Scoop layout; scoopRoots covers relocations.
71	const scoopAppsMarker = "/scoop/apps/"
72	
73	// scoopAppName returns the Scoop app directory the binary runs from ("cli" or
74	// "entire"), or "" when execPath is not under a Scoop apps root. This is the
75	// durable signal for the pre-rename package: a binary running from the `cli`
76	// app dir must migrate to `entire` regardless of its version (the fix ships in
77	// a final `cli` release, so the migrating binary's version is already past the
78	// rename).
79	func scoopAppName(execPath string) string {
80		for _, raw := range scoopRoots() {
81			root := normalizeInstallRoot(raw)
82			if root == "" {
83				continue
84			}
85			if below, ok := strings.CutPrefix(execPath, root); ok {
86				return firstPathSegment(below)
87			}
88		}
89		if _, below, ok := strings.Cut(execPath, scoopAppsMarker); ok {
90			return firstPathSegment(below)
91		}
92		return ""
93	}
94	
95	func firstPathSegment(p string) string {
96		app, _, _ := strings.Cut(p, "/")
97		return app
98	}
99	
100	func scoopUpgradeCommand(execPath, _ string) string {
101		// The Scoop package was renamed from `cli` to `entire`. A binary still
102		// running from the old `cli` app dir can never cross the rename with a
103		// plain `scoop update entire/cli`, so migrate it: install the new
104		// `entire` package, remove the old `cli` package, then reset the shared
105		// shims. Both manifests declare `bin: [git-remote-entire.exe,
106		// entire.exe]`, so the two packages contend for the same shims. Current
107		// Scoop handles that itself: installing `entire` renames the displaced
108		// shim to `entire.shim.cli` (warn_on_overwrite) and uninstalling `cli`
109		// removes only that suffixed copy (rm_shim), leaving the active shims
110		// pointing at `entire`. The reset step is belt-and-braces for older
111		// Scoop versions that overwrote shims without that alt-file dance and
112		// would otherwise take `entire.exe` and the git remote helper with them.
113		//
114		// The Windows updater is print-only, so return a self-contained command
115		// users can paste into either cmd or PowerShell. Explicitly invoking
116		// cmd.exe makes `&&` portable across those shells and ensures uninstall
117		// only runs after install succeeds — a stale bucket or transient failure
118		// therefore never removes the working CLI. (The uninstall→reset link is
119		// weaker: `scoop uninstall` ends in an unconditional `exit 0`, so reset
120		// runs even when the uninstall skipped its work. That is harmless, since
121		// reset is a no-op on the Scoop versions that make it unnecessary.)
122		//
123		// `scoop install` also auto-refreshes the bucket when >3h stale
124		// (is_scoop_outdated), so the new manifest usually lands
125		// without an explicit refresh; a bucket clone older than that check can
126		// still fail with "couldn't find manifest", and the README migration
127		// section names `scoop update` as the retry. Binaries already on the
128		// `entire` app just update in place.
129		if scoopAppName(execPath) == "cli" {
130			return `cmd.exe /D /C "scoop install entire/entire && scoop uninstall entire/cli && scoop reset entire"`
131		}
132		return "scoop update entire/entire"
133	}
134	
135	var scoopProbe = installProbe{
136		roots:   scoopRoots,
137		markers: []string{scoopAppsMarker},
138		command: scoopUpgradeCommand,
139	}
140	
141	var installProbes = []installProbe{scoopProbe, miseProbe}
142	
143	// fallbackInstallCommand names the running binary's directory with
144	// -InstallDir so install.ps1 replaces it in place instead of taking its
145	// Scoop-first default (an explicit -InstallDir opts out of Scoop there), and
146	// passes -NoPathUpdate so an update never rewrites the user PATH.
147	func fallbackInstallCommand(execPath, currentVersion string) string {
148		var args []string
149		if isNightly(currentVersion) {
150			args = append(args, "-Channel nightly")
151		}
152		if execPath != "" {
153			args = append(args, "-InstallDir '"+quoteInsideDoubleQuoted(filepath.Dir(execPath))+"' -NoPathUpdate")
154		}
155		if len(args) == 0 {
156			return windowsInstallCmd
157		}
158		return fmt.Sprintf(windowsInstallWithArgs, strings.Join(args, " "))
159	}
160	
161	// quoteInsideDoubleQuoted prepares a path for a single-quoted literal that
162	// itself sits inside a PowerShell double-quoted string. The outer string
163	// still expands $name and treats a backtick as an escape, so both are
164	// backtick-escaped; the inner single-quote literal needs a quote doubled.
165	func quoteInsideDoubleQuoted(p string) string {
166		r := strings.NewReplacer("`", "``", "$", "`$", "'", "''")
167		return r.Replace(p)
168	}
