8	type Policy struct {
9		CheckpointVersion    string `json:"checkpoint_version,omitempty"`
10		CheckpointMinVersion string `json:"checkpoint_min_version,omitempty"`
11	}
12	
13	func DefaultPolicy() Policy {
14		return Policy{
15			CheckpointVersion:    CheckpointVersionBranchV1,
16			CheckpointMinVersion: CheckpointVersionBranchV1,
17		}
18	}
19	
20	func DefaultCheckpointVersion() string {
21		return CheckpointVersionBranchV1
22	}
23	
24	func Normalize(policy Policy) Policy {
25		if policy.CheckpointVersion == "" {
26			policy.CheckpointVersion = DefaultCheckpointVersion()
27		}
28		if policy.CheckpointMinVersion == "" {
29			policy.CheckpointMinVersion = CheckpointVersionBranchV1
30		}
31		return policy
32	}
33	
34	func ValidatePolicy(policy Policy) error {
35		policy = Normalize(policy)
36	
37		version, err := ParseFormat(policy.CheckpointVersion)
38		if err != nil {
39			return fmt.Errorf("checkpoint_version: %w", err)
40		}
41		if !CanWrite(version) {
42			return fmt.Errorf("checkpoint_version %q is not supported by this Entire CLI", policy.CheckpointVersion)
43		}
44	
45		minVersion, err := ParseFormat(policy.CheckpointMinVersion)
46		if err != nil {
47			return fmt.Errorf("checkpoint_min_version: %w", err)
48		}
49		if !CanRead(minVersion) {
50			return fmt.Errorf("checkpoint_min_version %q is not supported by this Entire CLI", policy.CheckpointMinVersion)
51		}
52		if Compare(minVersion, version) > 0 {
53			return fmt.Errorf("checkpoint_min_version %q is newer than checkpoint_version %q", policy.CheckpointMinVersion, policy.CheckpointVersion)
54		}
55	
56		return nil
57	}
58	
59	func RequiresUpgrade(policy Policy) bool {
60		policy = Normalize(policy)
61		minVersion, err := ParseFormat(policy.CheckpointMinVersion)
62		if err != nil {
63			return true
64		}
65		return !CanRead(minVersion)
66	}
67	
68	func UnsupportedWrite(policy Policy) bool {
69		policy = Normalize(policy)
70		version, err := ParseFormat(policy.CheckpointVersion)
71		if err != nil {
72			return true
73		}
74		return !CanWrite(version)
75	}
76	
77	func CanSatisfyPolicy(policy Policy) bool {
78		return !UnsupportedWrite(policy) && !RequiresUpgrade(policy)
79	}
80	
81	func UnsupportedPolicyMessage(policy Policy, updateCommand string) string {
82		if CanSatisfyPolicy(policy) {
83			return ""
84		}
85	
86		var b strings.Builder
87		fmt.Fprintf(&b, "[entire] This repository requires checkpoint support newer than this Entire CLI.\n[entire] Upgrade Entire, then rerun the command:\n[entire]   %s\n", updateCommand)
88		details := unsupportedPolicyDetails(policy)
89		if len(details) == 0 {
90			return b.String()
91		}
92		b.WriteString("[entire] Details:\n")
93		for _, detail := range details {
94			fmt.Fprintf(&b, "[entire]   %s\n", detail)
95		}
96		return b.String()
97	}
98	
99	func unsupportedPolicyDetails(policy Policy) []string {
100		policy = Normalize(policy)
101		var details []string
102	
103		version, err := ParseFormat(policy.CheckpointVersion)
104		if err != nil {
105			details = append(details, fmt.Sprintf("checkpoint_version %q is invalid: %v.", policy.CheckpointVersion, err))
106		} else if !CanWrite(version) {
107			details = append(details, fmt.Sprintf("checkpoint_version %q is not writable by this Entire CLI; this CLI defaults to %q.", policy.CheckpointVersion, DefaultCheckpointVersion()))
108		}
109	
110		minVersion, err := ParseFormat(policy.CheckpointMinVersion)
111		if err != nil {
112			details = append(details, fmt.Sprintf("checkpoint_min_version %q is invalid: %v.", policy.CheckpointMinVersion, err))
113		} else if !CanRead(minVersion) {
114			details = append(details, fmt.Sprintf("checkpoint_min_version %q is not readable by this Entire CLI; this CLI can read %q.", policy.CheckpointMinVersion, DefaultCheckpointVersion()))
115		}
116	
117		return details
118	}
